package codegen

import (
	"cmp"
	"fmt"
	"go/format"
	"slices"

	"github.com/areqag/gqlc/internal/version"
)

// Header renders the "Code generated by gqlc ... DO NOT EDIT." header,
// byte-identical across files in a batch. The Go toolchain regex
// (^// Code generated .* DO NOT EDIT\.$) matches so gofmt / linters
// treat the files as generated.
func Header() string {
	return fmt.Sprintf("// Code generated by gqlc %s. DO NOT EDIT.\n\n", version.Version)
}

// Finalise gofmts every file's contents and sorts the set by Path — the
// emission tail every backend shares (§2.3). Contents a Go formatter
// rejects are a template bug and surface as ErrFormatFailure naming the
// offending path. Returns (nil, err) on failure, never a partial slice.
func Finalise(files []File) ([]File, error) {
	for i, f := range files {
		formatted, err := format.Source(f.Contents)
		if err != nil {
			return nil, fmt.Errorf("%w: %s: %w", ErrFormatFailure, f.Path, err)
		}
		files[i].Contents = formatted
	}
	slices.SortFunc(files, func(a, b File) int { return cmp.Compare(a.Path, b.Path) })
	return files, nil
}
